"""
test_flatten_dict.py
--------------------
Unit tests for flatten_dict using pytest.

The file contains a copy of the implementation so it can be run directly.
If the function is already importable, you can remove the duplicated definition
and just import it.
"""

import pytest
from typing import Any, Dict, Union

# ----------------------------------------------------------------------
# Implementation under test (kept here for a self‑contained example)
# ----------------------------------------------------------------------
def flatten_dict(d: dict, parent_key: str = '', sep: str = '.') -> dict:
    """
    Recursively flatten a nested dictionary.

    Parameters
    ----------
    d : dict
        The dictionary to flatten.
    parent_key : str, optional
        Prefix that should be prepended to the keys (used internally).
    sep : str, optional
        Separator inserted between nested key components.

    Returns
    -------
    dict
        A new (flattened) dictionary.
    """
    items = []
    for k, v in d.items():
        new_key = f'{parent_key}{sep}{k}' if parent_key else k
        if isinstance(v, dict):
            items.extend(flatten_dict(v, new_key, sep).items())
        else:
            items.append((new_key, v))
    return dict(items)


# ----------------------------------------------------------------------
# Helpers
# ----------------------------------------------------------------------
def assert_dict_equal(actual: Dict[Any, Any], expected: Dict[Any, Any]) -> None:
    """Simple helper that also checks that the result is a plain dict."""
    assert isinstance(actual, dict), "Result is not a dict"
    assert actual == expected, f'Expected {expected!r}, got {actual!r}'


# ----------------------------------------------------------------------
# Happy‑path tests
# ----------------------------------------------------------------------
class TestFlattenDictHappyPath:
    """Core functionality – the “happy” scenarios."""

    def test_flatten_simple_flat_dict(self):
        """A single‑level dict should be returned unchanged (keys stay the same)."""
        d = {'a': 1, 'b': 2}
        expected = {'a': 1, 'b': 2}
        assert_dict_equal(flatten_dict(d), expected)

    def test_flatten_two_levels(self):
        """One level of nesting."""
        d = {'a': {'b': 1, 'c': 2}, 'd': 3}
        expected = {'a.b': 1, 'a.c': 2, 'd': 3}
        assert_dict_equal(flatten_dict(d), expected)

    def test_flatten_three_levels(self):
        """Deep nesting."""
        d = {'x': {'y': {'z': 0}}, 'w': 1}
        expected = {'x.y.z': 0, 'w': 1}
        assert_dict_equal(flatten_dict(d), expected)

    def test_flatten_custom_separator(self):
        """Custom separator changes the key composition."""
        d = {'a': {'b': 1}}
        expected = {'a/b': 1}
        assert_dict_equal(flatten_dict(d, sep='/'), expected)

    def test_flatten_with_prefix(self):
        """Providing a parent_key adds a prefix to every key."""
        d = {'a': {'b': 1}, 'c': 2}
        expected = {'prefix.a.b': 1, 'prefix.c': 2}
        assert_dict_equal(flatten_dict(d, parent_key='prefix'), expected)

    def test_flatten_with_prefix_and_custom_separator(self):
        """Both prefix and custom separator."""
        d = {'a': {'b': 1}}
        expected = {'pre/a/b': 1}
        assert_dict_equal(flatten_dict(d, parent_key='pre', sep='/'), expected)

    def test_flatten_empty_dict(self):
        """An empty input dict yields an empty dict."""
        assert flatten_dict({}) == {}

    def test_flatten_with_empty_inner_dict(self):
        """Inner empty dict should be omitted from the result."""
        d = {'a': {}, 'b': 2}
        expected = {'b': 2}
        assert_dict_equal(flatten_dict(d), expected)

    def test_flatten_with_non_string_keys(self):
        """Non‑string keys (e.g. int) are converted to strings automatically."""
        d = {1: 'int_key', 'a': {2: 'nested_int_key'}}
        expected = {'1': 'int_key', 'a.2': 'nested_int_key'}
        assert_dict_equal(flatten_dict(d), expected)

    def test_flatten_does_not_modify_original(self):
        """Flattening must not mutate the supplied dictionary."""
        original = {'a': {'b': 1}}
        flatten_dict(original)   # type: ignore
        assert original == {'a': {'b': 1}}

    def test_flatten_list_values_stay_as_values(self):
        """Lists are not flattened (they are treated as leaf values)."""
        d = {'a': [1, 2, 3], 'b': {'c': 4}}
        expected = {'a': [1, 2, 3], 'b.c': 4}
        assert_dict_equal(flatten_dict(d), expected)

    @pytest.mark.parametrize(
        "input_dict, sep, expected",
        [
            ({'k': {'l': 1}}, '.', {'k.l': 1}),
            ({'k': {'l': 1}}, '-', {'k-l': 1}),
            ({'k': {'l': {'m': 2}}}, '/', {'k/l/m': 2}),
        ],
    )
    def test_flatten_parametrized_separator(self, input_dict, sep, expected):
        """Check that every separator produces the expected key format."""
        assert flatten_dict(input_dict, sep=sep) == expected


# ----------------------------------------------------------------------
# Edge‑case tests
# ----------------------------------------------------------------------
class TestFlattenDictEdgeCases:
    """Situations that are legal but may stress the logic."""

    def test_deep_nesting_many_levels(self):
        """Many nested levels – ensure recursion depth is fine for typical use."""
        deep = {'lvl0': {'lvl1': {'lvl2': {'lvl3': {'lvl4': 'deep'}}}}}
        expected = {'lvl0.lvl1.lvl2.lvl3.lvl4': 'deep'}
        assert_dict_equal(flatten_dict(deep), expected)

    def test_multiple_branches(self):
        """Multiple independent branches at the same level."""
        d = {
            'a': {'b': 1, 'c': 2},
            'd': {'e': 3},
            'f': 4,
        }
        expected = {'a.b': 1, 'a.c': 2, 'd.e': 3, 'f': 4}
        assert_dict_equal(flatten_dict(d), expected)

    def test_duplicate_keys_after_flattening(self):
        """If two different paths generate the same key, the later value wins."""
        d = {'a': {'b': 1}, 'a.b': 2}
        # flatten_dict builds items list left‑to‑right,
        # then creates dict -> later entries override earlier ones.
        result = flatten_dict(d)
        assert result == {'a.b': 2}

    def test_flatten_with_empty_string_key(self):
        """An empty string as a key is a legal key."""
        d = {'': 'empty_key', 'a': {'': 'nested_empty'}}
        expected = {'': 'empty_key', 'a.': 'nested_empty'}
        assert_dict_equal(flatten_dict(d), expected)

    def test_flatten_with_value_None(self):
        """None is a valid leaf value."""
        d = {'a': None, 'b': {'c': None}}
        expected = {'a': None, 'b.c': None}
        assert_dict_equal(flatten_dict(d), expected)

    def test_flatten_with_bool_values(self):
        """Booleans are leaf values."""
        d = {'x': True, 'y': {'z': False}}
        expected = {'x': True, 'y.z': False}
        assert_dict_equal(flatten_dict(d), expected)

    def test_flatten_with_numeric_leaf_values(self):
        """Numeric types (int, float, complex) are leaf values."""
        d = {
            'a': 42,
            'b': {'c': 3.14},
            'd': {'e': {'f': 1 + 2j}},
        }
        expected = {'a': 42, 'b.c': 3.14, 'd.e.f': 1 + 2j}
        assert_dict_equal(flatten_dict(d), expected)

    def test_flatten_with_dict_subclass(self):
        """A subclass of dict should be treated as a dict and flattened."""
        class MyDict(dict):
            pass

        d = MyDict({'a': MyDict({'b': 1})})
        expected = {'a.b': 1}
        assert_dict_equal(flatten_dict(d), expected)

    def test_flatten_preserves_insertion_order(self):
        """Since Python 3.7 dict preserves insertion order."""
        d = {chr(97 + i): {chr(97 + i * 2): i} for i in range(5)}
        result = flatten_dict(d)
        # Build expected list of keys in the order they would be generated
        expected_keys = [f"{chr(97 + i)}.{chr(97 + i*2)}" for i in range(5)]
        assert list(result.keys()) == expected_keys


# ----------------------------------------------------------------------
# Error‑case tests
# ----------------------------------------------------------------------
class TestFlattenDictErrors:
    """Situations that should raise an exception."""

    def test_non_dict_input_raises_type_error(self):
        """Passing a list (or any non‑dict) should raise TypeError."""
        with pytest.raises(TypeError, match="not supported"):
            flatten_dict([1, 2, 3])  # type: ignore

    def test_string_input_raises_type_error(self):
        """A string is not a dict."""
        with pytest.raises(TypeError):
            flatten_dict("not a dict")  # type: ignore

    def test_none_input_raises_type_error(self):
        """None is not a dict."""
        with pytest.raises(TypeError):
            flatten_dict(None)  # type: ignore

    def test_integer_input_raises_type_error(self):
        """An int is not a dict."""
        with pytest.raises(TypeError):
            flatten_dict(42)  # type: ignore

    @pytest.mark.parametrize("invalid_sep", [None, 123, [], {}])
    def test_invalid_separator_raises_type_error(self, invalid_sep):
        """Using a non‑string separator should raise TypeError (or at least be caught)."""
        # The implementation will try f"{parent_key}{sep}{k}" – if sep is not str,
        # the format call will raise TypeError. We treat that as an error case.
        with pytest.raises(TypeError):
            flatten_dict({'a': 1}, sep=invalid_sep)

    def test_non_str_parent_key_raises_type_error(self):
        """If parent_key cannot be concatenated as a string, a TypeError should be raised."""
        with pytest.raises(TypeError):
            flatten_dict({'a': 1}, parent_key=object())
```

### How to Run the Tests

1. **Save** the code above in a file named `test_flatten_dict.py` (or any name you like).
2. **Install pytest** if you haven’t already:

   ```bash
   pip install pytest
   ```

3. **Run the suite**:

   ```bash
   pytest test_flatten_dict.py -v
   ```

All tests are designed to pass with the reference implementation. They cover:

* **Happy‑path** – simple flattening, multi‑level nesting, custom separators, prefix handling, empty dicts, non‑string keys, and preservation of insertion order.
* **Edge‑cases** – deep nesting, multiple branches, duplicate keys after flattening, empty‑string keys, `None`/boolean/numeric leaf values, dict subclasses, and mixed leaf types.
* **Error‑cases** – passing a non‑dictionary, `None`, a string, an integer, or an invalid separator; also using a non‑string `parent_key`.

Feel free to adapt the import line (`from your_module import flatten_dict`) if the function lives elsewhere. The rest of the file works out‑of‑the‑box. Happy testing!
